function Roster({ publicData }) {
  const [active, setActive] = useState(null); // selected client
  // already scoped to notable=true server-side (see /api/public-data)
  const notableFor = (client) => (publicData?.notablePlacements || []).filter((p) => p.clientId === client.id);
  useEffect(() => {
    if (!active) return;
    const prev = document.body.style.overflow;
    document.body.style.overflow = "hidden";
    return () => { document.body.style.overflow = prev; };
  }, [active]);
  if (!publicData) return <main className="page page-wide"><p className="muted">Loading…</p></main>;
  return (
    <main className="page page-wide">
      <h1 className="page-head font-display">Roster</h1>
      <div className="ros-grid">
        {publicData.clients.map((c) => (
          <button key={c.id} className="ros-card" onClick={() => setActive(c)}>
            <div className="ros-photo">
              {c.photo ? <Photo src={c.photo} alt={c.name} fill /> : <div className="ros-photo-empty">{c.name[0].toUpperCase()}</div>}
            </div>
            <div className="ros-cap">
              <strong>{c.name}</strong>
              <span className="ros-role">{c.role}</span>
            </div>
          </button>
        ))}
      </div>

      {active && (
        <div className="modal artist-overlay" onClick={(e) => e.target === e.currentTarget && setActive(null)}>
          <div className="artist-panel">
            <button className="modal-x" onClick={() => setActive(null)}><X size={20} /></button>

            <div className="artist-top">
              <div className="artist-photo">
                {active.photo
                  // priority: this image is fully visible the instant the modal
                  // opens, so lazy-loading it (the default) fights the fade-in —
                  // on a slow connection the IntersectionObserver-driven fetch
                  // hasn't finished by the time someone looks, leaving it stuck
                  // on the gray placeholder background.
                  ? <Photo src={active.photo} alt={active.name} fill sizes="(max-width: 820px) 90vw, 480px" priority />
                  : <div className="artist-photo-empty">{active.name[0].toUpperCase()}</div>}
              </div>
              <div className="artist-info">
                <FitText tag="h2" text={active.name} className="artist-name font-display" />
                <span className="artist-role">{active.role}</span>
                <Socials c={active} size={26} />
                {active.bio && <p className="artist-bio">{active.bio}</p>}
              </div>
            </div>

            {notableFor(active).length > 0 && (
              <div className="artist-releases">
                <h3 className="artist-rel-head font-display">Notable Releases</h3>
                <div className="artist-rel-grid">
                  {notableFor(active).map((r) => {
                    const Tag = r.link ? "a" : "div";
                    return (
                      <Tag key={r.id} className="artist-rel-card" {...(r.link ? { href: r.link, target: "_blank", rel: "noreferrer" } : {})}>
                        <div className="artist-rel-cover">
                          {r.cover ? <Photo src={r.cover} alt={r.song} /> : <div className="artist-rel-cover-empty"><Disc3 size={34} /></div>}
                        </div>
                        <strong>{r.song}</strong>
                        <span>{r.artist}</span>
                      </Tag>
                    );
                  })}
                </div>
              </div>
            )}

            {!active.bio && !active.spotify && !active.apple && !active.youtube && !active.instagram && !active.tiktok && notableFor(active).length === 0 && (
              <p className="muted artist-empty">No links or releases added yet — staff can add them from the dashboard.</p>
            )}
          </div>
        </div>
      )}
    </main>
  );
}

function Contact() {
  const [f, setF] = useState({ name: "", email: "", instagram: "", subject: "General Inquiry", message: "" });
  const [sent, setSent] = useState(false);
  const [err, setErr] = useState(null);
  const [busy, setBusy] = useState(false);
  const [website, setWebsite] = useState(""); // honeypot — real visitors never see or fill this in
  const loadedAt = useRef(Date.now());
  const subjects = ["General Inquiry", "Artist Management", "Booking", "Publishing / Admin", "Sync Licensing", "Press / Media", "Other"];
  const submit = async () => {
    if (!f.name || !f.email || !f.instagram || !f.message) return;
    setBusy(true); setErr(null);
    try {
      const res = await fetch("/api/submit-contact", {
        method: "POST",
        headers: { "Content-Type": "application/json", "X-Requested-With": "defied-site" },
        body: JSON.stringify({ ...f, website, loadedAt: loadedAt.current }),
      });
      const data = await res.json();
      if (!res.ok) throw new Error(data.error || "Couldn't send that — try again.");
      setSent(true);
      setF({ name: "", email: "", instagram: "", subject: "General Inquiry", message: "" });
    } catch (e) {
      setErr(e.message || "Couldn't send that — try again.");
    } finally {
      setBusy(false);
    }
  };
  return (
    <main className="page contact">
      <h1 className="page-head">Let's Work.</h1>
      <p className="lead">Interested in working with us or have any questions? Please fill out this form and we'll get back to you as soon as possible.</p>
      {sent ? (
        <div className="sent">
          <Check size={28} />
          <h3>Message sent</h3>
          <p>We'll get back to you as soon as possible.</p>
        </div>
      ) : (
        <div className="form-card">
          {/* honeypot — hidden from real visitors via CSS, not type="hidden"
              (bots specifically skip type=hidden fields, but not off-screen ones) */}
          <input
            type="text" name="website" value={website} onChange={(e) => setWebsite(e.target.value)}
            autoComplete="off" tabIndex={-1} aria-hidden="true"
            style={{ position: "absolute", left: "-9999px", width: 1, height: 1, opacity: 0 }}
          />
          <Field label="Name" value={f.name} onChange={(e) => setF({ ...f, name: e.target.value })} />
          <Field label="Email" type="email" value={f.email} onChange={(e) => setF({ ...f, email: e.target.value })} />
          <Field label="Instagram" value={f.instagram} placeholder="@yourhandle" onChange={(e) => setF({ ...f, instagram: e.target.value })} />
          <label className="fld"><span>Subject</span>
            <select value={f.subject} onChange={(e) => setF({ ...f, subject: e.target.value })}>
              {subjects.map((s) => <option key={s}>{s}</option>)}
            </select>
          </label>
          <Area label="Message" value={f.message} onChange={(e) => setF({ ...f, message: e.target.value })} />
          {err && <p className="hint err-text">{err}</p>}
          <button className="btn" onClick={submit} disabled={busy}>{busy ? "Sending…" : "Send message"}</button>
        </div>
      )}
      <p className="muted">Or reach out directly — <EmailButton email="submissions@defiedmgmt.com" inline /> · <ExtLink className="inline-link" href="https://instagram.com/defiedmgmt">@defiedmgmt</ExtLink></p>
    </main>
  );
}

/* ------------------------------------------------------------------ */
/*  LOGIN                                                               */
/* ------------------------------------------------------------------ */
function Login({ login }) {
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [remember, setRemember] = useState(false);
  const [err, setErr] = useState(null);
  const [busy, setBusy] = useState(false);
  const submit = async () => {
    setBusy(true);
    const e = await login(email, password, remember);
    setBusy(false);
    setErr(e);
  };
  return (
    <main className="login">
      <Link href={ROUTE_TO_PATH.home} className="login-mark"><Wordmark height={40} /></Link>
      <div className="login-card">
        <h2>Sign in</h2>
        <p className="muted">Staff and client access.</p>
        <Field label="Email" value={email} onChange={(e) => setEmail(e.target.value)} onKeyDown={(e) => e.key === "Enter" && submit()} />
        <Field label="Password" type="password" value={password} onChange={(e) => setPassword(e.target.value)} onKeyDown={(e) => e.key === "Enter" && submit()} />
        <label className="check-row">
          <input type="checkbox" checked={remember} onChange={(e) => setRemember(e.target.checked)} />
          <span>Remember me on this device</span>
        </label>
        {err && <div className="err">{err}</div>}
        <button className="btn full" onClick={submit} disabled={busy}>{busy ? "Signing in…" : "Sign in"}</button>
        <Link href={ROUTE_TO_PATH.home} className="link-btn center">← Back to site</Link>
      </div>
    </main>
  );
}

